update T_SETTING
set sett_status = #{settStatus}
where sett_option_id = #{settOptionId}

update T_SETTING
set sett_status = 0
where sett_option_id <> #{settOptionId}
  and sett_staff_id = #{staffId}

UPDATE T_SETTING
set sett_priority = #{minSettPriority}
where sett_option_id = #{maxSettId}
  and sett_staff_id = #{staffId}

UPDATE T_SETTING
set sett_priority = #{maxSettPriority}
where sett_option_id = #{minSettId}
  and sett_staff_id = #{staffId}

UPDATE T_SETTING
set sett_priority = sett_priority - 1
where sett_priority > #{settPriority}
  and sett_staff_id = #{staffId}
